# -*- coding: utf-8 -*-
"""Plot cv.csv generated by mosfet.py cv."""

import pandas as pd
import plotly.express as px

df = pd.read_csv("cv.csv")

# Display capacitance in fF/µm for readability.
df["Cgg_fF_per_um"] = df["Cgg_F_per_um"] * 1.0e15

fig = px.line(
    df,
    x="Vg_V",
    y="Cgg_fF_per_um",
    markers=True,
    title="DEVSIM C–V Characteristics",
    labels={
        "Vg_V": "Vg (V)",
        "Cgg_fF_per_um": "Cgg (fF/µm)",
    },
)
fig.update_layout(height=500, margin=dict(l=50, r=30, t=60, b=50))
fig.show()
